fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based, convert to 0-based
    let k_zero_based = k - 1;
    
    // Create a new vector with capacity n-1
    let mut result = Vec::with_capacity(list.len() - 1);
    
    // Add elements before k
    result.extend_from_slice(&list[0..k_zero_based]);
    
    // Add elements after k
    result.extend_from_slice(&list[k_zero_based + 1..]);
    
    result
}